const categories = [
 {id:'ropita',name:'Ropita',line:'Para sus primeros abrazos',text:'Bodies, enteritos y conjuntos: ideas para vestir sus primeros días.',image:'nursery.jpg',alt:'Bebé con enterito de osito',description:'Una propuesta de bodies, enteritos y conjuntos para el día a día. Las prendas, tallas, materiales y precios del catálogo definitivo se confirmarán antes del lanzamiento.'},
 {id:'ajuares',name:'Ajuares',line:'Una dulce bienvenida',text:'Ideas para preparar su llegada y dar un regalo con cariño.',image:'baby.jpg',alt:'Bebé con body y lentes de sol',description:'Ideas de conjuntos de bienvenida y regalos para recién nacidos. El contenido de cada ajuar y sus precios se publicarán con el catálogo definitivo.'},
 {id:'accesorios',name:'Accesorios',line:'Detalles que acompañan',text:'Inspiración para completar su ropita y sus momentos de descanso.',image:'nursery.jpg',alt:'Enterito y manta de un bebé',description:'Una categoría para los pequeños complementos de cada día. Los accesorios disponibles, sus características y precios se confirmarán al lanzamiento.'},
 {id:'juguetes',name:'Juguetes',line:'Su primer descubrimiento',text:'Un espacio para el juego, los peluches y las nuevas aventuras.',image:'outfit.jpg',alt:'Bebé jugando con peluches',description:'Ideas de juguetes y peluches para sus primeros descubrimientos. Cada producto del catálogo definitivo indicará su edad recomendada y características.'}
];
const heart='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/></svg>';
let favorites=[];
try {const stored=JSON.parse(localStorage.getItem('trin1-favorites')||'[]');if(Array.isArray(stored))favorites=categories.filter(c=>stored.includes(c.id)).map(c=>c.id);}catch{}
let filter='Todo';const grid=document.querySelector('#products'),search=document.querySelector('#search'),dialog=document.querySelector('dialog'),content=document.querySelector('#dialog-content');
function render(){const query=search.value.trim().toLocaleLowerCase('es');const shown=categories.filter(c=>(filter==='Todo'||filter===c.name)&&`${c.name} ${c.text}`.toLocaleLowerCase('es').includes(query));grid.innerHTML=shown.map(c=>`<article class="product"><button class="product-link" data-detail="${c.id}" aria-label="Ver ${c.name}"><div class="product-photo"><img src="assets/${c.image}" alt="${c.alt}" loading="lazy" width="600" height="600" data-source="stand-in" data-subject="${c.id}"></div><div class="product-info"><span>${c.line}</span><h3>${c.name}</h3><p>${c.text}</p><div class="card-link">Ver categoría <span aria-hidden="true">↗</span></div></div></button><button class="favorite" data-save="${c.id}" aria-label="${favorites.includes(c.id)?'Quitar':'Guardar'} ${c.name} de favoritos" aria-pressed="${favorites.includes(c.id)}">${heart}</button></article>`).join('');document.querySelector('#empty').hidden=shown.length>0;document.querySelector('#saved-count').textContent=favorites.length;}
function setFilter(value){filter=value;document.querySelectorAll('.filters button').forEach(b=>{const active=b.dataset.filter===value;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);});render();}
let toastTimer;function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2400);}
function toggleSave(id){favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];try{localStorage.setItem('trin1-favorites',JSON.stringify(favorites));}catch{toast('Los favoritos se guardarán solo durante esta visita.');render();return;}render();toast(favorites.includes(id)?'Categoría guardada en tus favoritos':'Categoría eliminada de tus favoritos');}
function showSaved(){content.innerHTML='<p class="eyebrow">TU PEQUEÑA SELECCIÓN</p><h2 id="dialog-title">Tus favoritos</h2><p>Guardados en este navegador para tu próxima visita.</p>'+(favorites.length?favorites.map(id=>{const c=categories.find(x=>x.id===id);return `<div class="saved-item"><span>${c.name}</span><button data-remove="${id}" aria-label="Quitar ${c.name} de favoritos">Quitar</button></div>`;}).join(''):'<p>Aún no tienes favoritos. Guarda una categoría con el corazón de su tarjeta.</p>');if(!dialog.open)dialog.showModal();}
document.addEventListener('click',event=>{const f=event.target.closest('[data-filter]');if(f){setFilter(f.dataset.filter);document.querySelector('nav').classList.remove('open');document.querySelector('#menu-toggle').setAttribute('aria-expanded','false');}const save=event.target.closest('[data-save]');if(save){toggleSave(save.dataset.save);if(dialog.open){const c=categories.find(c=>c.id===save.dataset.save);save.textContent=favorites.includes(c.id)?'Quitar de favoritos':'Guardar en favoritos';}}const detail=event.target.closest('[data-detail]');if(detail){const c=categories.find(c=>c.id===detail.dataset.detail);content.innerHTML=`<img src="assets/${c.image}" alt="${c.alt}"><p class="eyebrow" style="margin-top:24px">COLECCIÓN DE MUESTRA</p><h2 id="dialog-title">${c.name}</h2><p>${c.description}</p><button class="button" data-save="${c.id}">${favorites.includes(c.id)?'Quitar de favoritos':'Guardar en favoritos'}</button>`;dialog.showModal();}const remove=event.target.closest('[data-remove]');if(remove){toggleSave(remove.dataset.remove);showSaved();}});
search.addEventListener('input',render);document.querySelector('#search-toggle').addEventListener('click',()=>{document.querySelector('#coleccion').scrollIntoView();search.focus({preventScroll:true});});document.querySelector('#saved-toggle').addEventListener('click',showSaved);document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});document.querySelector('#menu-toggle').addEventListener('click',event=>{const open=document.querySelector('nav').classList.toggle('open');event.currentTarget.setAttribute('aria-expanded',open);event.currentTarget.setAttribute('aria-label',open?'Cerrar menú':'Abrir menú');});document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('nav').classList.remove('open');document.querySelector('#menu-toggle').setAttribute('aria-expanded','false');}));render();
